function bssFixSupportMainLabelRunScript($, BSS_PL, page) {
  if(BSS_PL.page.isProductPage()){
      BSS_PL.settingsData.enableIntersection = true;
  }

  const style = document.createElement("style");
  style.innerHTML = `
    recently-viewed-products .bss_pl_img, 
    .geoip-popup-banner .bss_pl_img, 
    product-recommendations .bss_pl_img,
    product-recommendations .bss_pb_img {
        position: absolute !important;
        left: -99999px !important;
        visibility: hidden !important;
    }

    .bss_pb_img img,
    .bss_pl_img img,
    .bss_pb_img .bss_parent_text,
    .bss_pl_img .bss_parent_text {
      z-index: 1 !important;
    }

    .bss_pb_img:has(.bss-pb-stock-wrapper){
      width: unset !important;
      flex: 1 !important;
    }

    .product-info__block-list:has(.amazon-banner-link)>:not(:nth-child(1 of:not(:empty))){
      margin-top: 0 !important
    }

  `;

  document.head.append(style);
}

function bssFixSupportReInitLabel($, BSS_PL, firstLoadProduct, checkPageFly, initCollectionLabel, initBadge) {
  // Write code here
   if (window.location.pathname.includes('/products')) {
    const originalPushState = history.pushState;
    const originalReplaceState = history.replaceState;

    function onUrlChange() {
      $('.shopify-section--main-product .bss_pb_img:has([bss-config-id])').remove();
      $('.shopify-section--main-product .bss_pl_img:has([bss-config-id])').remove();
      BSS_PL.firstLoad = true;
      BSS_PL.init();
    }

    history.pushState = function (...args) {
      originalPushState.apply(history, args);
      onUrlChange();
    };

    history.replaceState = function (...args) {
      originalReplaceState.apply(history, args);
      onUrlChange();
    };

    window.addEventListener('popstate', onUrlChange);
  }
  return { firstLoadProduct, checkPageFly };
}

function bssFixSupportFirstImageLabel($, page, parent, labeledParent, index, isActive) {
  // Write code here
  if ($(parent).is(".product-gallery__image-list .product-gallery__media")) {
    if (
      labeledParent.get(index) !== undefined &&
      labeledParent.get(index) != null &&
      labeledParent.get(index).includes('rimage-wrapper')
    ) {
      isActive = false;
    } else {
      labeledParent.set(index, ['rimage-wrapper']);
    }
  }
  return isActive;
}

function bssFixSupportExcludeItem($, page, item) {
  // Write code here
  if($(item).is(".icart-cart-main a")){
      return true;
  }
  return false;
}

function bssFixSupportTurnOffThumbnailResize() {
  return false
}

function bssFixSupportMainPriceForBadgePrice($, parent, page, mainPrice) {
  // Write code here
    if($(parent).is(".product-gallery__media")){
        mainPrice = $(parent).closest('.container').find(".price-list");
    }
  return mainPrice;
}

function bssFixSupportPriceElementForBadgePrice($, parent, page, priceEl) {
  // Write code here
  if($(parent).is(".product-card__figure")){
      priceEl = $(parent).closest('.product-card').find(".price-list");
  }
  return priceEl;
}

function bssFixSupportFindPriceElementForBadgeName($, BSS_PL, priceEl, parent, page) {
  // Write code here
  if ($(parent).is('.product-card__figure')) {
    priceEl = $(parent).closest(".product-card").find(".product-title")
  }
  return priceEl;
}

function bssFixSupportTurnOnGetProductJsonData() {
