body.script:
(function() {
  function publishEvent(eventName, eventData) {
    try {
      if (window.Shopify && Shopify.analytics && typeof Shopify.analytics.publish === 'function') {
        Shopify.analytics.publish(eventName, eventData || {});
      }
    } catch (e) {
      console.warn('Failed to publish Shopify analytics event:', eventName, e);
    }
  }

  function getSearchKeywordFromReferrer() {
    var referrer = document.referrer;
    if (!referrer) return null;

    try {
      var url = new URL(referrer);
      var hostname = url.hostname.toLowerCase();

      var keyword =
        url.searchParams.get('q') ||
        url.searchParams.get('query') ||
        url.searchParams.get('keyword') ||
        url.searchParams.get('p') ||
        url.searchParams.get('wd');

      if (!keyword) return null;

      return {
        keyword: keyword,
        hostname: hostname,
        referrer: referrer,
        landing_page: window.location.href
      };
    } catch (e) {
      return null;
    }
  }

  document.addEventListener('DOMContentLoaded', function() {
    var searchData = getSearchKeywordFromReferrer();
    if (searchData) {
      publishEvent('anua:search_keyword', searchData);
    }

    document.querySelectorAll('.js-meta-amazon-click').forEach(function(el) {
      el.addEventListener('click', function() {
        publishEvent('anua:amazon_click', {
          product_id: el.getAttribute('data-product-id'),
          destination: el.getAttribute('data-destination'),
          page_path: window.location.pathname
        });
      });
    });
  });

  window.addEventListener('klaviyoForms', function(e) {
    if (e.detail && e.detail.type === 'submit') {
      publishEvent('anua:klaviyo_submit', {
        form_id: e.detail.formId || null,
        page_path: window.location.pathname,
        page_url: window.location.href
      });
    }
  });
})();

document.addEventListener("fg-gifts:gift-icon", async (e) => {
  e.detail.gifts.forEach(function(gift){
    let items = document.querySelectorAll('.glider.fg-gift-thumbnail-offer-slider .product-item')
    if(items){
      items.forEach((productItemEl)=>{
        const price = window.FGSECOMAPP.helper.formatter.format(gift.variants[0].original_price);
        const lastHref = productItemEl.querySelector(".gift-original-url")?.getAttribute("href")?.split("/")
        const isAddCustomEl = lastHref[lastHref.length - 1] == gift.handle;
        if (isAddCustomEl) {
          productItemEl.innerHTML += '
'+ gift.title +'';
        }
      })
    }
  });
});

